    ('55becbab-2d3c-5c37-b08e-b31526d560db'::uuid, 'Quiz — Un proton qui change de main', 'Physique-Chimie', 'Tle', 'Acides et bases selon Brönsted', '269303d6-54d1-5170-8dc9-b451b853fb08'::uuid),
    ('8953758c-b874-59e3-b905-880918f6488f'::uuid, 'Quiz — Une échelle logarithmique, pas une échelle de valeurs', 'Physique-Chimie', 'Tle', 'Le pH des solutions', 'fdf272ba-05bf-5583-acab-649c94de74be'::uuid),
